/** Replaced at build time from TELEGRAM_API_ID / TELEGRAM_API_HASH (electron.vite.config.ts →
 * define). Unset in dev builds and any build without the env — the app then falls back to
 * asking the user for their own credentials. */
declare const __PLEXO_TG_API_ID__: number | undefined
declare const __PLEXO_TG_API_HASH__: string | undefined
